[metadata] {"type": "create", "filePath": "/app/output/daly_shift.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Disease Burden Transition 1990–2024</title>
<link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #f7f4ef;
    --surface: #ffffff;
    --surface-2: #f0ece4;
    --border: rgba(60,50,30,0.12);
    --border-strong: rgba(60,50,30,0.22);
    --text: #1a1612;
    --text-dim: #6b6158;
    --text-muted: #9a9188;

    --comm: #c2410c;       /* communicable – terracotta */
    --comm-dim: #fde8dc;
    --comm-mid: #ea7a44;
    --ncd: #0369a1;        /* NCD – steel blue */
    --ncd-dim: #dbeafe;
    --ncd-mid: #3b8fc4;
    --injury: #59792e;     /* injury – sage */
    --injury-dim: #ecf4d9;
    --injury-mid: #85aa4c;

    --font-body: 'IBM Plex Sans', system-ui, sans-serif;
    --font-serif: 'Instrument Serif', Georgia, serif;
    --font-mono: 'IBM Plex Mono', monospace;

    --radius: 6px;
    --shadow: 0 1px 4px rgba(0,0,0,0.08), 0 2px 12px rgba(0,0,0,0.05);
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: var(--font-body);
    font-size: 14px;
    line-height: 1.5;
  }

  /* ── Page shell ── */
  .page {
    width: 1400px;
    min-height: 1000px;
    padding: 48px 52px 56px;
    margin: 0 auto;
    background: var(--bg);
  }

  /* ── Header ── */
  .masthead {
    border-top: 3px solid var(--text);
    padding-top: 18px;
    margin-bottom: 36px;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 32px;
  }
  .masthead-left { flex: 1; }
  .kicker {
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-bottom: 8px;
  }
  .title {
    font-family: var(--font-serif);
    font-size: 34px;
    line-height: 1.15;
    color: var(--text);
    margin-bottom: 8px;
  }
  .subtitle {
    font-size: 13.5px;
    color: var(--text-dim);
    max-width: 640px;
    line-height: 1.6;
  }
  .legend-global {
    display: flex;
    gap: 20px;
    align-items: center;
    flex-shrink: 0;
    padding-top: 4px;
  }
  .legend-item {
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: 12px;
    color: var(--text-dim);
    font-family: var(--font-mono);
  }
  .legend-dot {
    width: 12px; height: 12px;
    border-radius: 2px;
    flex-shrink: 0;
  }

  /* ── Grid layout ── */
  .grid {
    display: grid;
    grid-template-columns: 320px 1fr 1fr;
    grid-template-rows: auto auto;
    gap: 20px;
  }

  /* ── Cards ── */
  .card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    overflow: hidden;
  }
  .card-header {
    padding: 14px 18px 10px;
    border-bottom: 1px solid var(--border);
  }
  .card-label {
    font-family: var(--font-mono);
    font-size: 9.5px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 4px;
  }
  .card-title {
    font-family: var(--font-serif);
    font-size: 17px;
    color: var(--text);
    line-height: 1.2;
  }
  .card-body { padding: 16px 18px; }

  /* ── Section A: Global totals donut pair ── */
  .donuts-area {
    display: flex;
    flex-direction: column;
    gap: 20px;
    padding: 16px 18px;
  }
  .donut-row {
    display: flex;
    align-items: center;
    gap: 14px;
  }
  .donut-year {
    font-family: var(--font-serif);
    font-size: 28px;
    color: var(--text);
    line-height: 1;
    min-width: 48px;
  }
  .donut-wrap {
    position: relative;
    width: 90px;
    height: 90px;
    flex-shrink: 0;
  }
  .donut-wrap canvas { width: 90px !important; height: 90px !important; }
  .donut-meta {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 5px;
  }
  .donut-stat {
    font-size: 11.5px;
    color: var(--text-dim);
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .donut-stat strong {
    font-weight: 600;
    font-family: var(--font-mono);
    font-size: 12px;
  }
  .stat-swatch {
    display: inline-block;
    width: 7px; height: 7px;
    border-radius: 1px;
    margin-right: 4px;
    vertical-align: middle;
  }
  .donut-total {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--text-muted);
    margin-top: 6px;
    padding-top: 6px;
    border-top: 1px solid var(--border);
  }

  /* ── Section B: Income group stacked bars ── */
  .income-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px 20px;
    padding: 16px 18px;
  }
  .income-block { }
  .income-label {
    font-size: 10.5px;
    color: var(--text-dim);
    font-family: var(--font-mono);
    margin-bottom: 8px;
    font-weight: 500;
  }
  .year-bar-row {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 6px;
  }
  .bar-year {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--text-muted);
    min-width: 28px;
  }
  .stacked-bar {
    flex: 1;
    height: 18px;
    border-radius: 3px;
    overflow: hidden;
    display: flex;
  }
  .bar-seg {
    height: 100%;
    transition: none;
  }
  .seg-comm { background: var(--comm); }
  .seg-ncd  { background: var(--ncd); }
  .seg-inj  { background: var(--injury); }
  .bar-pct {
    font-family: var(--font-mono);
    font-size: 9px;
    color: var(--text-muted);
    min-width: 26px;
    text-align: right;
  }

  /* ── Section C: Bump / rank chart ── */
  .bump-wrap {
    padding: 10px 18px 16px;
    position: relative;
  }

  /* ── Section D: horizontal bar chart for top causes ── */
  .causes-wrap {
    padding: 10px 18px 14px;
  }

  /* ── Annotations ── */
  .annotation-strip {
    grid-column: 1 / -1;
    display: flex;
    gap: 14px;
  }
  .annotation-card {
    flex: 1;
    background: var(--surface-2);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 12px 16px;
    display: flex;
    align-items: flex-start;
    gap: 10px;
  }
