<script>
// ── Donut charts ──
const donutCfg = (comm, ncd, inj) => ({
  type: 'doughnut',
  data: {
    datasets: [{
      data: [comm, ncd, inj],
      backgroundColor: ['#c2410c','#0369a1','#59792e'],
      borderWidth: 1.5,
      borderColor: '#fff',
      hoverOffset: 2
    }]
  },
  options: {
    cutout: '62%',
    responsive: false,
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    animation: { duration: 0 }
  }
});

const ctx1990 = document.getElementById('donut1990').getContext('2d');
const ctx2024 = document.getElementById('donut2024').getContext('2d');
document.getElementById('donut1990').width  = 90;
document.getElementById('donut1990').height = 90;
document.getElementById('donut2024').width  = 90;
document.getElementById('donut2024').height = 90;
new Chart(ctx1990, donutCfg(1128.4, 768.2, 253.7));
new Chart(ctx2024, donutCfg(612.5, 1487.3, 308.6));


// ── Bump / rank chart (SVG) ──
(function() {
  const causes1990 = [
    { cause: 'Lower resp. infections', rank: 1, category: 'Communicable' },
    { cause: 'Diarrheal diseases',      rank: 2, category: 'Communicable' },
    { cause: 'Neonatal preterm birth',  rank: 3, category: 'Communicable' },
    { cause: 'Ischemic heart disease',  rank: 4, category: 'NCD' },
    { cause: 'Stroke',                  rank: 5, category: 'NCD' },
    { cause: 'Malaria',                 rank: 6, category: 'Communicable' },
    { cause: 'Tuberculosis',            rank: 7, category: 'Communicable' },
    { cause: 'Measles',                 rank: 8, category: 'Communicable' },
    { cause: 'COPD',                    rank: 9, category: 'NCD' },
    { cause: 'Road injuries',           rank:10, category: 'Injury' },
  ];
  const causes2024 = [
    { cause: 'Ischemic heart disease',  rank: 1, category: 'NCD' },
    { cause: 'Stroke',                  rank: 2, category: 'NCD' },
    { cause: 'Diabetes mellitus',       rank: 3, category: 'NCD' },
    { cause: 'COPD',                    rank: 4, category: 'NCD' },
    { cause: 'Neonatal preterm birth',  rank: 5, category: 'Communicable' },
    { cause: 'Lower resp. infections',  rank: 6, category: 'Communicable' },
    { cause: 'Low back pain',           rank: 7, category: 'NCD' },
    { cause: 'Depressive disorders',    rank: 8, category: 'NCD' },
    { cause: 'Road injuries',           rank: 9, category: 'Injury' },
    { cause: 'Lung cancer',             rank:10, category: 'NCD' },
  ];

  const allCauses = [...new Set([
    ...causes1990.map(d=>d.cause),
    ...causes2024.map(d=>d.cause)
  ])];

  const catColor = { NCD: '#0369a1', Communicable: '#c2410c', Injury: '#59792e' };

  const svg = document.getElementById('bump-svg');
  const W = 380, H = 310;
  const LEFT = 130, RIGHT = W - 110;
  const TOP = 28, BOT = H - 20;
  const rowH = (BOT - TOP) / 9;

  function rankY(rank) { return TOP + (rank - 1) * rowH; }

  // Year labels
  const yLabel1990 = document.createElementNS('http://www.w3.org/2000/svg','text');
  yLabel1990.setAttribute('x', LEFT); yLabel1990.setAttribute('y', 14);
  yLabel1990.setAttribute('text-anchor','middle');
  yLabel1990.setAttribute('fill','#1a1612'); yLabel1990.setAttribute('font-family','IBM Plex Mono,monospace');
  yLabel1990.setAttribute('font-size','11'); yLabel1990.setAttribute('font-weight','500');
  yLabel1990.textContent = '1990';
  svg.appendChild(yLabel1990);

  const yLabel2024 = document.createElementNS('http://www.w3.org/2000/svg','text');
  yLabel2024.setAttribute('x', RIGHT); yLabel2024.setAttribute('y', 14);
  yLabel2024.setAttribute('text-anchor','middle');
  yLabel2024.setAttribute('fill','#1a1612'); yLabel2024.setAttribute('font-family','IBM Plex Mono,monospace');
  yLabel2024.setAttribute('font-size','11'); yLabel2024.setAttribute('font-weight','500');
  yLabel2024.textContent = '2024';
  svg.appendChild(yLabel2024);

  // Draw lines for causes that appear in both years
  for (const cause of allCauses) {
    const d1 = causes1990.find(d=>d.cause===cause);
    const d2 = causes2024.find(d=>d.cause===cause);
    if (!d1 || !d2) continue;

    const cat = d1.category;
    const color = catColor[cat];
    const y1 = rankY(d1.rank);
    const y2 = rankY(d2.rank);
    const cx1 = LEFT + 18, cx2 = RIGHT - 18;

    // Curved bump path
    const path = document.createElementNS('http://www.w3.org/2000/svg','path');
    const midX = (cx1 + cx2) / 2;
    path.setAttribute('d', `M${cx1},${y1} C${midX},${y1} ${midX},${y2} ${cx2},${y2}`);
    const rankDelta = d1.rank - d2.rank; // positive = improved (went up)
    const strokeW = Math.abs(rankDelta) >= 4 ? 2.5 : (Math.abs(rankDelta) >= 2 ? 2 : 1.2);
    path.setAttribute('stroke', color);
    path.setAttribute('stroke-width', strokeW);
    path.setAttribute('fill', 'none');
    path.setAttribute('opacity', Math.abs(rankDelta) >= 2 ? '0.9' : '0.45');
    svg.appendChild(path);
  }

  // Draw 1990 circles + labels
  for (const d of causes1990) {
    const y = rankY(d.rank);
    const color = catColor[d.category];
    const circle = document.createElementNS('http://www.w3.org/2000/svg','circle');
    circle.setAttribute('cx', LEFT); circle.setAttribute('cy', y);
    circle.setAttribute('r', 9); circle.setAttribute('fill', color);
    circle.setAttribute('opacity','0.92');
    svg.appendChild(circle);
    // rank number
    const rankTxt = document.createElementNS('http://www.w3.org/2000/svg','text');
    rankTxt.setAttribute('x', LEFT); rankTxt.setAttribute('y', y + 4);
    rankTxt.setAttribute('text-anchor','middle'); rankTxt.setAttribute('fill','#fff');
    rankTxt.setAttribute('font-family','IBM Plex Mono,monospace'); rankTxt.setAttribute('font-size','9');
    rankTxt.setAttribute('font-weight','500'); rankTxt.textContent = d.rank;
    svg.appendChild(rankTxt);
    // label left
    const lbl = document.createElementNS('http://www.w3.org/2000/svg','text');
    lbl.setAttribute('x', LEFT - 14); lbl.setAttribute('y', y + 4);
    lbl.setAttribute('text-anchor','end'); lbl.setAttribute('fill', color);
    lbl.setAttribute('font-family','IBM Plex Sans,sans-serif'); lbl.setAttribute('font-size','9');
    lbl.setAttribute('font-weight', ['Ischemic heart disease','Stroke','COPD'].includes(d.cause)?'400':'400');
    lbl.textContent = d.cause;
    svg.appendChild(lbl);
  }

  // Draw 2024 circles + labels
  for (const d of causes2024) {
    const y = rankY(d.rank);
    const color = catColor[d.category];
    // look up 1990 rank for context
    const prev = causes1990.find(p=>p.cause===d.cause);
    const rankDelta = prev ? prev.rank - d.rank : null;

    const circle = document.createElementNS('http://www.w3.org/2000/svg','circle');
    circle.setAttribute('cx', RIGHT); circle.setAttribute('cy', y);
    circle.setAttribute('r', 9); circle.setAttribute('fill', color);
    circle.setAttribute('opacity','0.92');
    svg.appendChild(circle);
    // rank number
    const rankTxt = document.createElementNS('http://www.w3.org/2000/svg','text');
    rankTxt.setAttribute('x', RIGHT); rankTxt.setAttribute('y', y + 4);
    rankTxt.setAttribute('text-anchor','middle'); rankTxt.setAttribute('fill','#fff');
    rankTxt.setAttribute('font-family','IBM Plex Mono,monospace'); rankTxt.setAttribute('font-size','9');
    rankTxt.setAttribute('font-weight','500'); rankTxt.textContent = d.rank;
    svg.appendChild(rankTxt);
    // label right
    const lbl = document.createElementNS('http://www.w3.org/2000/svg','text');
    lbl.setAttribute('x', RIGHT + 14); lbl.setAttribute('y', y + 4);
    lbl.setAttribute('text-anchor','start'); lbl.setAttribute('fill', color);
    lbl.setAttribute('font-family','IBM Plex Sans,sans-serif'); lbl.setAttribute('font-size','9');
    lbl.textContent = d.cause;
    svg.appendChild(lbl);

    // delta annotation
    if (rankDelta !== null && Math.abs(rankDelta) >= 3) {
      const arrow = rankDelta > 0 ? '▲' : '▼';
      const annColor = rankDelta > 0 ? '#059669' : '#9f1239';
      const ann = document.createElementNS('http://www.w3.org/2000/svg','text');
      ann.setAttribute('x', RIGHT + 14 + 82); ann.setAttribute('y', y + 4);
      ann.setAttribute('fill', annColor); ann.setAttribute('font-family','IBM Plex Mono,monospace');
      ann.setAttribute('font-size','8.5'); ann.setAttribute('font-weight','600');
      ann.textContent = `${arrow}${Math.abs(rankDelta)}`;
      svg.appendChild(ann);
    }
  }

  // Draw new entries in 2024 (not in top 10 of 1990)
  const newIn2024 = causes2024.filter(d => !causes1990.find(p=>p.cause===d.cause));
  for (const d of newIn2024) {
    const y = rankY(d.rank);
    // small "new" badge
    const badge = document.createElementNS('http://www.w3.org/2000/svg','text');
    badge.setAttribute('x', RIGHT + 14 + 70); badge.setAttribute('y', y + 4);
    badge.setAttribute('fill','#6b7280'); badge.setAttribute('font-family','IBM Plex Mono,monospace');
    badge.setAttribute('font-size','7.5'); badge.setAttribute('font-style','italic');
    badge.textContent = 'new';
    svg.appendChild(badge);
  }
})();


// ── Horizontal grouped bar chart for top 10 causes ──
(function() {
  const causes1990 = [
    { cause: 'Lower resp. infections', dalys: 178.5, category: 'Communicable' },
    { cause: 'Diarrheal diseases',      dalys: 155.2, category: 'Communicable' },
    { cause: 'Neonatal preterm birth',  dalys: 103.8, category: 'Communicable' },
    { cause: 'Ischemic heart disease',  dalys:  98.6, category: 'NCD' },
    { cause: 'Stroke',                  dalys:  82.4, category: 'NCD' },
    { cause: 'Malaria',                 dalys:  78.1, category: 'Communicable' },
    { cause: 'Tuberculosis',            dalys:  72.3, category: 'Communicable' },
    { cause: 'Measles',                 dalys:  65.9, category: 'Communicable' },
    { cause: 'COPD',                    dalys:  57.2, category: 'NCD' },
    { cause: 'Road injuries',           dalys:  52.7, category: 'Injury' },
  ];
  const causes2024 = [
    { cause: 'Ischemic heart disease',  dalys: 192.3, category: 'NCD' },
    { cause: 'Stroke',                  dalys: 147.8, category: 'NCD' },
    { cause: 'Diabetes mellitus',       dalys: 118.4, category: 'NCD' },
    { cause: 'COPD',                    dalys: 105.1, category: 'NCD' },
    { cause: 'Neonatal preterm birth',  dalys:  82.6, category: 'Communicable' },
    { cause: 'Lower resp. infections',  dalys:  78.3, category: 'Communicable' },
    { cause: 'Low back pain',           dalys:  74.9, category: 'NCD' },
    { cause: 'Depressive disorders',    dalys:  68.5, category: 'NCD' },
    { cause: 'Road injuries',           dalys:  63.2, category: 'Injury' },
    { cause: 'Lung cancer',             dalys:  58.7, category: 'NCD' },
  ];

  // Merge all unique causes (union of both lists)
  const allCauses = [...new Set([
    ...causes2024.map(d=>d.cause),
    ...causes1990.map(d=>d.cause),
  ])];

  const lookup90 = Object.fromEntries(causes1990.map(d=>[d.cause, d]));
  const lookup24 = Object.fromEntries(causes2024.map(d=>[d.cause, d]));

  // color per cause based on 2024 category (or 1990 if not in 2024)
  const catColor = { NCD: '#0369a1', Communicable: '#c2410c', Injury: '#59792e' };
  const catColorDim = { NCD: '#93c5fd', Communicable: '#fca380', Injury: '#a3c56a' };

  const data1990 = allCauses.map(c => lookup90[c]?.dalys ?? 0);
  const data2024 = allCauses.map(c => lookup24[c]?.dalys ?? 0);
  const bgColors1990 = allCauses.map(c => {
    const cat = (lookup90[c]||lookup24[c])?.category;
